// nf-core modules test pangolin/updatedata
nextflow_process {

    name "Test Process PANGOLIN_UPDATEDATA"
    script "../main.nf"
    process "PANGOLIN_UPDATEDATA"

    tag "modules"
    tag "modules_nfcore"
    tag "pangolin"
    tag "pangolin/updatedata"

    test("str - testdb") {

        when {
            process {
                """
                input[0] = 'testdb'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out, unstableKeys: ["report"])).match() }
            )
        }
    }

    test("str - testdb - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = 'testdb'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }
}
